    static Box createLoop() {
        Box first = new Box();
        Object[] values = new Object[239];
        for (int i = 0; i < values.length; i++) values[i] = new Box();
        sink = values;
        return first;
    }

    public static String run(boolean loop) {
        completed = 0;
        for (; completed < 200; completed++) {
            Box first = loop ? createLoop() : createUnrolled();
            if (first.value == null) throw new AssertionError("Missing field value");
        }
        return "PASS: " + completed + " calls completed";
    }

    public static String describe(Throwable error) {
        java.io.StringWriter text = new java.io.StringWriter();
        error.printStackTrace(new java.io.PrintWriter(text));
        return text.toString();
    }

    public static void main(String[] args) {
        System.out.println(run(args.length > 0 && args[0].equals("loop")));
    }
